def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n < 5:
        return 'C'

    last_my, last_opp = history[-1]
    prev_opp = history[-2][1]

    opp_d = 0
    my_d = 0
    opp_d5 = 0
    my_d5 = 0
    opp_d10 = 0
    punish_total = 0
    punish = 0

    start5 = n - 5
    start10 = n - 10
    if start5 < 0:
        start5 = 0
    if start10 < 0:
        start10 = 0

    for i in range(n):
        my = history[i][0]
        opp = history[i][1]
        if opp == 'D':
            opp_d += 1
        if my == 'D':
            my_d += 1
        if i >= start5:
            if opp == 'D':
                opp_d5 += 1
            if my == 'D':
                my_d5 += 1
        if i >= start10 and opp == 'D':
            opp_d10 += 1

    for i in range(1, n):
        if history[i - 1][0] == 'D':
            punish_total += 1
            if history[i][1] == 'D':
                punish += 1

    opp_d_streak = 0
    for pair in reversed(history):
        if pair[1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for pair in reversed(history):
        if pair[0] == 'D':
            my_d_streak += 1
        else:
            break

    # If the partner has never punished a single defection, test carefully.
    # Avoid a perfect alternating pattern, which some tolerant strategies detect.
    if opp_d == 0:
        if last_my == 'D':
            if n >= 95:
                return 'D'
            if n >= 70 and rng.random() < 0.25:
                return 'D'
            return 'C'

        if n >= 70:
            p = 0.92
        elif n >= 40:
            p = 0.85
        else:
            p = 0.72

        if rng.random() < p:
            return 'D'
        return 'C'

    # Clear hostility: defect to avoid being used as a stepping stone.
    if opp_d10 >= 7 or opp_d_streak >= 6 or (n >= 30 and opp_d > my_d + 8):
        if last_my == 'D' and last_opp == 'D':
            if opp_d_streak <= 2 and opp_d5 <= 2 and rng.random() < 0.35:
                return 'C'
        return 'D'

    # Main conditional cooperation and punishment.
    if last_opp == 'D':
        # Sustained or repeated defection is punished, but short mutual
        # defection is not allowed to become a permanent death spiral.
        if prev_opp == 'D' or opp_d_streak >= 2:
            if last_my == 'D':
                # Both just defected. Try one olive branch if the opponent
                # is not deeply hostile or if our own D-streak is already long.
                if opp_d_streak <= 2 and opp_d5 <= 2 and opp_d <= my_d + 3:
                    if rng.random() < 0.45:
                        return 'C'
                if opp_d_streak <= 3 and my_d_streak >= 3:
                    if rng.random() < 0.35:
                        return 'C'
                if opp_d_streak <= 2 and rng.random() < 0.2:
                    return 'C'
                return 'D'

            # Opponent defected twice while we cooperated. Punish, but leave a
            # small chance of stopping a cycle if they were only retaliating.
            if opp_d_streak == 2 and opp_d5 <= 2 and opp_d <= my_d + 2:
                if rng.random() < 0.18:
                    return 'C'
            return 'D'

        # A single opponent D: usually forgive when the interaction is otherwise
        # cooperative, but lightly deter repeat offenders.
        if last_my == 'D':
            # Their D is likely punishment for ours; stop by cooperating.
            return 'C'

        if opp_d5 >= 3 or opp_d > my_d + 2:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    if last_my == 'D':
        # If they did not punish our last D, exploit occasionally, but do not
        # turn a forgiving partner into a cycle of alternating retaliation.
        if opp_d <= 4:
            if punish_total == 0:
                if rng.random() < 0.4:
                    return 'D'
            elif punish * 3 <= punish_total:
                if rng.random() < 0.6:
                    return 'D'
            elif punish * 2 <= punish_total and opp_d <= 2:
                if rng.random() < 0.35:
                    return 'D'
        return 'C'

    # Mutual cooperation: preserve it. Only probe against partners who have
    # repeatedly tolerated our D while still looking cooperative.
    if opp_d <= 3 and my_d > 0 and punish_total >= 3 and punish == 0:
        if rng.random() < 0.18:
            return 'D'

    return 'C'
